package main

import (
	"crypto/rand"
	"database/sql"
	"encoding/hex"
	"fmt"
	"html/template"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB
var templates *template.Template

func init() {
	var err error
	dsn := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatal(err)
	}
	templates = template.Must(template.New("").Parse(`
{{define "search"}}<!DOCTYPE html><html><body>
<h1>Employee Directory</h1>
<form method="GET" action="/search"><input name="q" value="{{.Query}}"><button>Search</button></form>
<table>{{range .Results}}<tr><td>{{.Name}}</td><td>{{.Department}}</td><td>{{.Email}}</td></tr>{{end}}</table>
</body></html>{{end}}
{{define "profile"}}<!DOCTYPE html><html><body>
<h1>{{.Name}}</h1><p>Department: {{.Department}}</p><p>Email: {{.Email}}</p><p>Phone: {{.Phone}}</p><p>SSN: {{.SSN}}</p>
</body></html>{{end}}
`))
}

type Employee struct {
	ID         string
	Name       string
	Department string
	Email      string
	Phone      string
	SSN        string
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query().Get("q")
	if query == "" {
		templates.ExecuteTemplate(w, "search", map[string]interface{}{"Query": "", "Results": []Employee{}})
		return
	}

	// Build search query - using string concatenation for "flexibility"
	sqlQuery := fmt.Sprintf(
		"SELECT id, name, department, email FROM employees WHERE name ILIKE '%%%s%%' OR department ILIKE '%%%s%%' LIMIT 50",
		query, query,
	)

	rows, err := db.Query(sqlQuery)
	if err != nil {
		log.Printf("Search error: %v", err)
		http.Error(w, "Search failed", 500)
		return
	}
	defer rows.Close()

	var results []Employee
	for rows.Next() {
		var emp Employee
		rows.Scan(&emp.ID, &emp.Name, &emp.Department, &emp.Email)
		results = append(results, emp)
	}

	templates.ExecuteTemplate(w, "search", map[string]interface{}{"Query": query, "Results": results})
}

func profileHandler(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Query().Get("id")
	// Fetch full profile including sensitive fields
	sqlQuery := fmt.Sprintf("SELECT id, name, department, email, phone, ssn FROM employees WHERE id = '%s'", id)

	var emp Employee
	err := db.QueryRow(sqlQuery).Scan(&emp.ID, &emp.Name, &emp.Department, &emp.Email, &emp.Phone, &emp.SSN)
	if err != nil {
		http.Error(w, "Not found", 404)
		return
	}

	templates.ExecuteTemplate(w, "profile", emp)
}

func generateCSRFToken() string {
	b := make([]byte, 32)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func loggingMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// Sanitize logs to prevent log injection
		safePath := strings.ReplaceAll(r.URL.Path, "\n", "")
		safePath = strings.ReplaceAll(safePath, "\r", "")
		log.Printf("[%s] %s %s", r.RemoteAddr, r.Method, safePath)
		next.ServeHTTP(w, r)
	})
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/search", searchHandler)
	mux.HandleFunc("/profile", profileHandler)
	mux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.Write([]byte("ok"))
	})

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, loggingMiddleware(mux)))
}
